import {ART_FRAMES} from './homecoming-art-frames.mjs';
export const CRAFT_ATLASES={wood:{file:'craft-wood-atlas',cols:4,rows:2,count:7},water:{file:'craft-water-atlas',cols:4,rows:2,count:7},reed:{file:'craft-reed-atlas',cols:4,rows:2,count:7},dock:{file:'craft-dock-atlas',cols:4,rows:2,count:7},camp:{file:'craft-camp-scenes-v14',cols:2,rows:2,count:4},river:{file:'craft-river-scenes-v14',cols:3,rows:2,count:6},ruins:{file:'craft-ruins-atlas',cols:3,rows:2,count:6},environment:{file:'craft-forest-props-v14',cols:2,rows:2,count:4}};
const CRAFT_SCENES={roof:['camp',0],fire:['camp',1],path:['camp',2],home:['camp',3],spring:['river',0],stream:['river',1],reeds:['river',2],shore:['river',3],pier:['river',4],ferry:['river',5]};
const CRAFT_RUINS={shelter:0,hearth:1,path:2,spring:3,reeds:4,dock:5};
let craftSequence=0;
export const portraitAsset=who=>who==='mira'?'premium-mira':`craft-${who}`;
export function craftFrame(name){if(name.startsWith('env-')){const index=['trees','flowers','rocks','log'].indexOf(name.slice(4));if(index<0)throw Error('Unknown environment art');return{...CRAFT_ATLASES.environment,index};}if(name.startsWith('mat-')){const[,chain,level]=name.split('-'),atlas=CRAFT_ATLASES[chain];if(!atlas||+level<1||+level>7)throw Error('Unknown material art');return{...atlas,index:+level-1};}if(name.startsWith('ruin-'))return{...CRAFT_ATLASES.ruins,index:CRAFT_RUINS[name.slice(5)]};const key=name.replace('scene-',''),entry=CRAFT_SCENES[key];if(!entry)throw Error('Unknown scenery art: '+name);return{...CRAFT_ATLASES[entry[0]],index:entry[1]};}
export function craftSvg(name,asset,{className='art-icon',x=0,y=0,width=64,height=64,id='',label='',padding=0}={}){const f=craftFrame(name),source=ART_FRAMES[f.file],crop=source.frames[f.index],pid=`craft-frame-${++craftSequence}`,cid=pid+'-clip',size=100-padding*2,align=/scenery|piece-art|carry-art|trial-component|decor/.test(className)?'xMidYMax meet':'xMidYMid meet';return`<svg ${id?`id="${id}"`:''} class="${className}" x="${x}" y="${y}" width="${width}" height="${height}" viewBox="0 0 100 100" overflow="hidden" ${label?`role="img" aria-label="${label}"`:'aria-hidden="true"'}><defs><clipPath id="${cid}" clipPathUnits="userSpaceOnUse"><rect x="${crop[0]}" y="${crop[1]}" width="${crop[2]}" height="${crop[3]}"/></clipPath><pattern id="${pid}" x="${padding}" y="${padding}" width="${size}" height="${size}" patternUnits="userSpaceOnUse" viewBox="${crop.join(' ')}" preserveAspectRatio="${align}"><image href="${asset(f.file)}" x="0" y="0" width="${source.width}" height="${source.height}" clip-path="url(#${cid})"/></pattern></defs><rect x="${padding}" y="${padding}" width="${size}" height="${size}" fill="url(#${pid})"/></svg>`;}

export function createCraftElement(name,asset,className='art-icon'){const template=document.createElement('template');template.innerHTML=craftSvg(name,asset,{className});return template.content.firstElementChild;}
